/* PRODUCT_CURRENT: shared, resettable catalog. No real codes, stock migration or database. */
(function(){'use strict';
const clone=x=>structuredClone(x),defs=[['UPPER','上衣尺码',['165/S','170/M','175/L','180/XL','185/2XL','190/3XL','195/4XL','200/5XL','205/6XL','无尺码']],['PANTS','裤子尺码',['30','31','32','33','34','35','36','38','40','无尺码']],['SHOES','鞋码',['38','39','40','41','42','43','44']],['KIDS','童装尺码',['90','100','110','120','130','140']],['FREE','配饰均码',['均码']]];
const C={groups:defs.map(([id,name,names])=>({id,name,sizes:names.map((name,i)=>({id:id+'-demo-size-'+i,name,code:''}))})),colors:[['0','不分色'],['000','统色'],['001','A'],['002','B'],['101','红色']].map(([code,name])=>({id:'color-'+code,code,name,disabled:false,demo:false})),fits:[{id:'regular',code:'DEMO-REG',name:'常规版',disabled:false},{id:'slim',code:'DEMO-SLIM',name:'修身版',disabled:false},{id:'straight',code:'DEMO-STR',name:'直筒版',disabled:false}],suppliers:[{id:'demo-supplier-1',code:'DEMO-GYS01',name:'示例供应商 · 华成服饰',type:'供应商'},{id:'demo-supplier-2',code:'DEMO-GYS02',name:'示例供应商 · 瑞丰制衣',type:'供应商'},{id:'demo-supplier-3',code:'DEMO-GYS03',name:'示例供应商 · 远山贸易',type:'供应商'}],categories:[{id:'all',name:'全部商品',parent:null,order:0},{id:'mens',name:'男装',parent:'all',order:0},{id:'tops',name:'上装',parent:'mens',order:0},{id:'shirts',name:'衬衫',parent:'tops',order:0},{id:'jackets',name:'夹克',parent:'tops',order:1},{id:'bottoms',name:'下装',parent:'mens',order:1},{id:'pants',name:'裤装',parent:'bottoms',order:0}],schemes:[],defaultScheme:'2023'};
for(const [id,name,prefix,length,parts,priority] of [['2020','2020年新方案','0',14,[['goods',7],['color',3],['size',3]],4],['2018','2018年货品','8',9,[['free',5],['color',1],['size',2]],5],['2021','2021年条码方案','6',13,[['goods',7],['color',3],['size',2]],3],['2021fit','2021年版型条码方案','2',14,[['goods',7],['fit',1],['color',3],['size',2]],2],['2023','2023年条码方案','9',14,[['goods',7],['color',3],['size',3]],1]])C.schemes.push({id,name,prefix,length,parts:parts.map(([key,length])=>({key,length})),priority,symbology:'Code128',type:'解析'});
C.seasons=Object.freeze(['春季','夏季','秋季','冬季','春夏','秋冬'].map(name=>Object.seal(Object.defineProperties({disabled:false},{id:{value:name,enumerable:true},name:{value:name,enumerable:true}}))));
let D;const color=id=>C.colors.find(x=>x.id===id),group=id=>C.groups.find(x=>x.id===id),fit=id=>C.fits.find(x=>x.id===id),by=id=>D.products.find(p=>p.id===id),sk=(c,s)=>c+'|'+s;
C.initialize=function(data){D=data;D.counterparties=C.suppliers;D.catalog=C;
 D.products.forEach((p,i)=>{if(p.sizeSystem==='legacy')return;p.sizeSystem='standard';p.groupId=p.category==='裤装'?'PANTS':'UPPER';p.colorIds=p.colors.map(name=>{let c=C.colors.find(x=>x.name===name);if(!c){c={id:'demo-color-'+C.colors.length,code:'',name,disabled:false,demo:true};C.colors.push(c)}return c.id});p.sizeIds=group(p.groupId).sizes.map(x=>x.id);p.sizes=group(p.groupId).sizes.map(x=>x.name);
 // Rebuild only synthetic fixture dimensions; no inference about historical business size mappings.
 D.warehouses.forEach(w=>{p.stock[w.id]=p.colors.map((_,c)=>p.sizeIds.map((_,s)=>p.stock[w.id]?.[c]?.[s]??0))});
 p.categoryId=({'衬衫':'shirts','夹克':'jackets','裤装':'pants'})[p.category]||'shirts';p.fitId=C.fits.find(f=>f.name===p.fit)?.id||'';p.supplierId=C.suppliers[i%3].id;p.purchasePrice=null;p.schemeId='2023';p.goodsCode='';p.freeCode='';p.images=[];p.barcodes={};p.colors.forEach((_,c)=>p.sizes.forEach((_,s)=>{p.barcodes[sk(p.colorIds[c],p.sizeIds[s])]={current:s!==9?'BC-'+p.id+'-'+(c+1)+'-'+(s+1):'',history:['OLD-'+p.id+'-'+(c+1)+'-'+(s+1),...(c===0&&s===0?['OLD2-'+p.id+'-1-1']:[])],demo:true}}));delete p.brand;
 });

};
C.color=color;C.group=group;C.fit=fit;C.by=by;C.specKey=sk;C.clone=clone;
C.path=function(id){const names=[],seen=new Set();while(id&&id!=='all'&&!seen.has(id)){seen.add(id);const c=C.categories.find(c=>c.id===id);if(!c)break;names.unshift(c.name);id=c.parent}return names.join(' / ')};
C.inCategory=function(p,id){if(!id||id==='all')return true;let cur=p.categoryId;const seen=new Set();while(cur&&!seen.has(cur)){if(cur===id)return true;seen.add(cur);cur=C.categories.find(x=>x.id===cur)?.parent}return false};
C.categoryNodes=function(){return C.categories.map(c=>({...c,level:Math.max(0,C.path(c.id).split(' / ').length-1),value:c.name}));};
C.barcodeValues=b=>[b.current,...(b.history||[]),...(b.compatible||[]).map(x=>x.code)];
C.importedFacts=barcodes=>Object.fromEntries(Object.entries(barcodes).map(([k,b])=>{const {compatible,...facts}=b;return [k,facts]}));
C.barcode=function(pid,c,s,old=false){const p=by(pid),r=p?.barcodes[sk(p.colorIds[c],p.sizeIds[s])];return old?(r?.history||[]).join(' / '):r?.current||''};
C.resolve=function(raw){const text=raw.trim();const matches=[];let historical=false;for(const p of D.products)for(let c=0;c<p.colorIds.length;c++)for(let s=0;s<p.sizeIds.length;s++){const b=p.barcodes[sk(p.colorIds[c],p.sizeIds[s])];if(b&&text&&C.barcodeValues(b).includes(text)){matches.push({p,c,s});historical ||= b.history.includes(text)}}
 if(matches.length)return {kind:matches.length>1?'ambiguous':historical?'historical':'current',matches,reason:window.REAL_DATA_MODE?'已登记的规格条码':'已绑定条码优先；Demo / 未业务核验'};
 if(window.REAL_DATA_MODE&&D.products.some(p=>p.excelBarcodeAuthority?.active))return {kind:'missing',matches:[],reason:'此条码未登记在已确认的条码表中'};
 if(text==='AMB-001')return {kind:'ambiguous',matches:[{p:D.products[0],c:0,s:0},{p:D.products[1],c:0,s:0}],reason:'隔离 Demo 歧义样本'};
 const candidates=[],unmapped=[];for(const scheme of C.schemes.filter(s=>s.id!=='2026'&&(!window.REAL_DATA_MODE||s.id==='2023')).sort((a,b)=>a.priority-b.priority)){if(text.length!==scheme.length||!text.startsWith(scheme.prefix))continue;let start=scheme.prefix.length,parts={};for(const x of scheme.parts){parts[x.key]=text.slice(start,start+x.length);start+=x.length}const found=[];for(const p of D.products){if(parts.goods&&(!(p.barcodeItemCode||p.goodsCode)||(p.barcodeItemCode||p.goodsCode)!==parts.goods))continue;if(parts.free&&(!p.freeCode||p.freeCode!==parts.free))continue;if(parts.fit&&fit(p.fitId)?.code!==parts.fit)continue;for(let c=0;c<p.colorIds.length;c++)for(let s=0;s<p.sizeIds.length;s++){if(color(p.colorIds[c])?.code===parts.color&&C.sizeRecords(p).find(x=>x.id===p.sizeIds[s])?.code===parts.size&&parts.color&&parts.size)found.push({p,c,s})}}if(found.length)candidates.push({scheme,parts,found});else unmapped.push({scheme,parts})}
 if(candidates.length){const x=candidates[0];return {kind:x.found.length>1?'ambiguous':'parsed',matches:x.found,scheme:x.scheme,parts:x.parts,reason:'方案解析；资料匹配结果仍为前端 Demo / 未业务核验'}}
 return {kind:'missing',matches:[],scheme:unmapped[0]?.scheme,parts:unmapped[0]?.parts,reason:unmapped.length?'结构命中，但货号 / 颜色 / 尺码映射缺失；未猜测':'没有明确绑定，也没有匹配的识别码与长度'};
};
C.search=function(q){q=q.trim();if(!q)return D.products.slice(0,30);const r=C.resolve(q);if(r.matches.length)return [...new Set(r.matches.map(x=>x.p))];return D.products.filter(p=>(p.id+' '+p.name).toLowerCase().includes(q.toLowerCase())).slice(0,30)};
C.newProduct=()=>{const sizeGroup=group('UPPER')||C.groups[0]||{id:'',sizes:[]};return {sizeSystem:'standard',id:'',name:'',categoryId:'',category:'',fitId:window.REAL_DATA_MODE?'A':'regular',fitIds:window.REAL_DATA_MODE?['A']:['regular'],baseFitId:window.REAL_DATA_MODE?'A':'regular',fit:'A版（标准）',supplierId:'',groupId:sizeGroup.id,colorIds:[],sizeIds:sizeGroup.sizes.map(x=>x.id),colors:[],sizes:sizeGroup.sizes.map(x=>x.name),enabled:true,price:null,purchasePrice:null,season:'',schemeId:C.defaultScheme,goodsCode:'',freeCode:'',barcodes:{},images:[],stock:Object.fromEntries(D.warehouses.map(w=>[w.id,[]]))}};
C.sizeRecords=p=>{const source=p.sizeSystem==='legacy'?(p.legacySizeRecords||[]):(group(p.groupId)?.sizes||[]);if(!window.REAL_DATA_MODE)return source.filter(x=>!Array.isArray(p.selectedSizeIds)||p.selectedSizeIds.includes(x.id));const available=new Map([...(p.legacySizeRecords||[]),...(p.specSizeRecords||[]),...(group(p.groupId)?.sizes||C.groups.flatMap(g=>g.sizes))].map(x=>[x.id,x]));const ids=Array.isArray(p.selectedSizeIds)?p.selectedSizeIds:p.sizeIds?.length?p.sizeIds:source.map(x=>x.id);return ids.map(id=>available.get(id)).filter(Boolean)};
C.prepare=function(p){if(p.sizeSystem==='legacy'&&!window.REAL_DATA_MODE)return p;p.colorIds=[...new Set(p.colorIds)];p.colors=p.colorIds.map(id=>color(id)?.name||'未找到颜色');p.sizeIds=C.sizeRecords(p).map(x=>x.id);p.sizes=C.sizeRecords(p).map(x=>x.name);p.fit=fit(p.fitId)?.name||'';p.category=C.categories.find(c=>c.id===p.categoryId)?.name||'';return p};
function remapReferences(p,next){const ci=c=>next.colorIds.indexOf(p.colorIds[c]),si=s=>next.sizeIds.indexOf(p.sizeIds[s]),mapKey=k=>{const [id,c,s,w]=k.split('|');if(id!==p.id)return k;return [id,ci(+c),si(+s),...(w?[w]:[])].join('|')};const docs=new Set([...(window.GOLD?.documents||[]),window.GOLD_UI?.state.currentDoc].filter(Boolean));for(const d of docs){d.q=Object.fromEntries(Object.entries(d.q).map(([k,v])=>[mapKey(k),v]));if(d.snapshot){const x=JSON.parse(d.snapshot);x.q=Object.fromEntries(Object.entries(x.q).map(([k,v])=>[mapKey(k),v]));d.snapshot=JSON.stringify(x)}for(const x of d.applied||[])if(x.p===p.id){x.c=ci(x.c);x.s=si(x.s)}for(const x of d.scans||[])if(x.p===p.id){x.c=ci(x.c);x.s=si(x.s);x.key=mapKey(x.key)}d.hiddenColors=(d.hiddenColors||[]).map(k=>{const [id,c]=k.split('|');return id===p.id?id+'|'+ci(+c):k})}if(window.GOLD){for(const e of GOLD.events)if(e.key.startsWith(p.id+'|'))e.key=mapKey(e.key);const entries=[...GOLD.initial.entries()].filter(([k])=>k.startsWith(p.id+'|'));for(const [k]of entries)GOLD.initial.delete(k);for(const [k,v]of entries)GOLD.initial.set(mapKey(k),v)}}
C.validate=function(p,original){if(!p.id.trim()||!p.name.trim())return '请填写款号和商品名称';if((!original||p.id!==original.id)&&!/^[A-Za-z0-9_-]+$/.test(p.id))return '款号请使用字母、数字、短横线或下划线';if(D.products.some(x=>x.id===p.id&&x!==original))return '款号已存在';if(!C.categories.some(c=>c.id===p.categoryId&&c.id!=='all')&&!(original&&p.categoryId===original.categoryId))return '请选择商品分类';if(!C.suppliers.some(s=>s.id===p.supplierId)&&!(original&&p.supplierId===original.supplierId))return '请选择默认供应商';if((p.sizeSystem!=='legacy'&&!group(p.groupId))||(p.fitId&&!fit(p.fitId)))return '请选择有效的尺码组和版型';if((!p.colorIds.length&&!(original?.sizeSystem==='legacy'&&original.colorIds.length===0))||p.colorIds.some(id=>!color(id))&&!(original?.sizeSystem==='legacy'&&JSON.stringify(p.colorIds)===JSON.stringify(original.colorIds)))return '请至少选择一个有效颜色';if(p.season&&!(C.validSeasons?C.validSeasons(p):C.seasons.some(s=>s.name===p.season&&!s.disabled))&&p.season!==original?.season)return '请选择标准季节';if(p.price!=null&&p.price!==''&&(!Number.isFinite(Number(p.price))||Number(p.price)<0)||p.purchasePrice!=null&&p.purchasePrice!==''&&(!Number.isFinite(Number(p.purchasePrice))||Number(p.purchasePrice)<0))return '价格必须是有效的非负金额，采购价可留空';if(p.images.some(im=>im.role==='颜色配图'&&!(window.REAL_DATA_MODE?p.selectedColorIds??p.colorIds:p.colorIds).includes(im.colorId)&&!(window.REAL_DATA_MODE&&original?.images?.some(old=>old.id===im.id&&old.role===im.role&&old.colorId===im.colorId&&old.url===im.url))))return '颜色配图请选择本商品已选颜色';const localCodes=new Map();for(const [,b] of Object.entries(p.barcodes)){for(const code of C.barcodeValues(b).filter(Boolean)){if(localCodes.has(code)&&localCodes.get(code)!==key)return '同一条码不能绑定多个规格';localCodes.set(code,key)}}for(const other of D.products.filter(x=>x!==original)){for(const b of Object.values(other.barcodes)){if(C.barcodeValues(b).some(code=>code&&localCodes.has(code)))return '条码已经绑定其他商品'}}if(original){if(p.id!==original.id)return '已有商品款号作为引用标识，本轮不重编';const removed=original.colorIds.some(id=>!p.colorIds.includes(id))||original.sizeIds.some(id=>!p.sizeIds.includes(id));if(removed&&!window.REAL_DATA_MODE){const referenced=Object.values(original.barcodes).some(b=>b.current||b.history.length||b.compatible?.length)||Object.values(original.stock).flat(2).some(n=>n!==0)||(window.GOLD?.documents||[]).some(d=>d.items.includes(original.id))||window.GOLD_UI?.state.currentDoc?.items.includes(original.id);if(referenced)return '现有规格已有条码、库存或单据引用，不能直接移除。可增加颜色；换组请用新建商品验证，避免破坏引用。'}}return ''};
// Session-only allocation. A production backend must allocate atomically with a unique constraint.
C.allocateItemCode=function(p){const used=new Set(D.products.flatMap(x=>[x.barcodeItemCode,x.goodsCode]).filter(Boolean));for(const x of D.products)for(const b of Object.values(x.barcodes||{}))for(const v of C.barcodeValues(b))if(/^9\d{7}.{6}$/.test(v||''))used.add(v.slice(1,8));for(let n=1;n<=9999999;n++){const code=String(n).padStart(7,'0');if(!used.has(code)){p.barcodeItemCode=code;return {ok:true}}}return {error:'系统暂时无法分配条码，请稍后重试。'}};
// Explicit read-only reference index boundary for future imported business snapshots. No real history is loaded.
C.historicalReferences=[];
C.deletionIssue=function(kind,id,drafts=[]){const rows=C[kind],x=rows?.find(x=>x.id===id),label={categories:'分类',colors:'颜色',fits:'版型',groups:'尺码组',seasons:'季节'}[kind];if(!label||!x||id==='all')return '该资料不能删除';if(kind==='categories'&&C.categories.some(c=>c.parent===id))return '当前分类下还有子分类，请先处理子分类后再删除。';const refers=p=>kind==='categories'?p.categoryId===id:kind==='colors'?(p.colorIds||[]).includes(id):kind==='fits'?(p.fitIds||[p.fitId]).includes(id):kind==='seasons'?C.seasonValues(p).includes(id):p.groupId===id;const referenced=D.products.some(refers)||drafts.filter(Boolean).some(refers)||C.historicalReferences.some(ref=>ref.kind===kind&&ref.id===id)||x.hasHistoricalReferences||x.historicalReferenceCount>0;if(referenced)return '当前'+label+'已被商品或历史数据引用，无法删除。';return ''};
C.deleteMaster=function(kind,id,drafts=[]){if(window.MASTER_DATA?.active&&!MASTER_DATA.canManage('products'))return {error:'当前账号无权维护商品资料'};const error=C.deletionIssue(kind,id,drafts);if(error)return {error};C[kind].splice(C[kind].findIndex(x=>x.id===id),1);return {ok:true}};
C.save=function(draft,original,options={}){if(window.MASTER_DATA?.active&&!MASTER_DATA.canManage('products'))return {error:'当前账号无权维护商品资料'};if(original?.sizeSystem==='legacy'&&draft.sizeSystem!=='legacy')return {error:'历史商品不能转换到新尺码体系'};if(draft.sizeSystem==='legacy'){if(original&&JSON.stringify(C.importedFacts(draft.barcodes))!==JSON.stringify(C.importedFacts(original.barcodes)))return {error:'历史条码为导入事实，不能在商品页改写'};if(!original)return {error:'历史商品需由原始商品及规格资料接入，本页不从尺码表创建历史商品'};if(JSON.stringify([draft.sizeIds,draft.colorIds,draft.legacySizeRecords,draft.groupId])!==JSON.stringify([original.sizeIds,original.colorIds,original.legacySizeRecords,original.groupId]))return {error:'历史尺码与原规格关系只读保留，不转换或重编'};}const p=C.prepare(clone(draft)),error=C.validate(p,original);if(error)return {error};let barcodeNotice='';if(options.autoBarcode&&p.sizeSystem!=='legacy'){p.schemeId=p.schemeId||C.defaultScheme;if(p.barcodeItemCode){if(D.products.some(x=>x.id!==p.id&&x.barcodeItemCode===p.barcodeItemCode))return {error:'系统货号已被其他商品使用'};}else {const allocated=C.allocateItemCode(p);if(allocated.error)return allocated;}const health=C.barcodeHealth(p);if(health.ok){const result=C.generate(p);if(result.error)return {error:result.error};barcodeNotice='商品已保存；自动补齐 '+result.count+' 个新规格条码（Demo）'}else barcodeNotice='商品资料已保存；条码资料尚未完整，补齐后再次保存。'}p.price=p.price==null||p.price===''?null:+p.price;p.purchasePrice=p.purchasePrice==null||p.purchasePrice===''?null:+p.purchasePrice;p.id=p.id.trim();p.name=p.name.trim();p.stock=Object.fromEntries(D.warehouses.map(w=>[w.id,p.colorIds.map(cid=>p.sizeIds.map(sid=>{const c=original?.colorIds.indexOf(cid),s=original?.sizeIds.indexOf(sid);return c>=0&&s>=0?original.stock[w.id][c][s]:0}))]));
 const valid=new Set(p.sizeSystem==='legacy'?Object.keys(original.barcodes):p.colorIds.flatMap(c=>p.sizeIds.map(s=>sk(c,s))));p.barcodes=Object.fromEntries(Object.entries(p.barcodes).filter(([k])=>valid.has(k)));for(const k of valid)p.barcodes[k]??={current:'',history:[],demo:true};if(original){remapReferences(original,p);Object.assign(original,p)}else{p.createdAt=p.createdAt||new Date().toISOString();D.products.push(p)};if(window.GOLD)D.warehouses.forEach(w=>p.colorIds.forEach((_,c)=>p.sizeIds.forEach((_,s)=>{const k=[p.id,c,s,w.id].join('|');if(!GOLD.initial.has(k))GOLD.initial.set(k,0)})));return {ok:true,product:original||p,barcodeNotice}};
// Pure, eager validation; changing a scheme never mutates a barcode binding.
C.barcodeHealth=function(p,options={}){
 const scheme=C.schemes.find(s=>s.id===p.schemeId),issues=[];
 if(!scheme)return {ok:false,issues:[{text:'请选择有效条码方案',target:'scheme'}]};
 const g=p.sizeSystem==='legacy'?{sizes:C.sizeRecords(p)}:group(p.groupId);if(!p.colorIds.length)issues.push({text:'尚未选择商品颜色',target:'specs'});
 if(!g)issues.push({text:'尚未选择有效尺码组',target:'groups'});
 for(const part of scheme.parts){
  if(part.key==='color'){const bad=p.colorIds.map(color).filter(c=>!c||String(c.code||'').length!==part.length);if(bad.length)issues.push({text:bad.map(c=>c?.name||'未知颜色').join('、')+(bad.every(c=>!c?.code)?'尚未设置颜色编码':'的颜色编码需为 '+part.length+' 位'),target:'colors'});}
  else if(part.key==='size'){const bad=(g?.sizes||[]).filter(s=>String(s.code||'').length!==part.length);if(bad.length)issues.push({text:bad.slice(0,3).map(s=>s.name).join('、')+(bad.length>3?'等 '+bad.length+' 个尺码':'')+(bad.every(s=>!s.code)?'尚未设置尺码编码':'的尺码编码需为 '+part.length+' 位'),target:'groups'});}
  else {if(part.key==='goods'&&options.userFacing)continue;const value=part.key==='goods'?(p.barcodeItemCode||p.goodsCode):part.key==='free'?p.freeCode:fit(p.fitId)?.code;const label={goods:'商品货号',free:'商品自由编码',fit:'版型条码码'}[part.key];if(String(value||'').length!==part.length)issues.push({text:label+'需 '+part.length+' 位，当前'+(value?'为 '+String(value).length+' 位':'未设置'),target:part.key==='fit'?'fits':part.key});}
 }
