function find(el){const q=el.value;E.pending.query=q;E.pending.productId='';E.pending.colorId='';E.pending.fitId='';E.pending.quantities={};E.pending.confirmedColor=false;const color=$('#mx-transfer-color'),fit=$('#mx-transfer-fit');for(const [control,label]of [[color,'颜色'],[fit,'版型']])if(control){control.disabled=true;if(control.tagName==='SELECT')control.value='';else{control.querySelector('span').textContent=label;control.classList.remove('has-value')}}document.querySelectorAll('[data-mx-replace-qty],[data-mx=replace-apply],[data-mx-draft-qty]').forEach(x=>x.disabled=true);const name=el.parentElement.querySelector('.mx-inline-name');if(name)name.textContent='';showFinder(el)}
function afterScan(result){if(!result?.ok||!active())return;const p=product(result.productId),c=Number(result.colorIndex);if(!p||!Number.isInteger(c))return;E.chosen.add(p.id+'|'+c);if(result.newProduct)p.colors.forEach((_,index)=>{if(index!==c&&!T.doc.hiddenColors.includes(p.id+'|'+index))T.doc.hiddenColors.push(p.id+'|'+index)});window.render();revealRow(p,c,result.key)}
function afterSkuDelete(key){if(!active())return;const [id,c]=key.split('|'),colorKey=id+'|'+c;if(!Object.entries(T.doc.q).some(([k,n])=>k.startsWith(colorKey+'|')&&Number(n)>0)){E.chosen.delete(colorKey);if(!T.doc.hiddenColors.includes(colorKey))T.doc.hiddenColors.push(colorKey)}if(!Object.entries(T.doc.q).some(([k,n])=>k.startsWith(id+'|')&&Number(n)>0))T.doc.items=T.doc.items.filter(item=>item!==id);window.render()}

