document.addEventListener('click',e=>{const b=e.target.closest('[data-mx]');if(!b)return;const a=b.dataset.mx;if(a==='history-qty')return openHistoryQuantities(b);if(a==='spec-color'||a==='spec-fit')return openSpecMenu(b);if(a==='close')return close();if(a==='confirm'){const fn=confirm;if(fn&&fn()!==false)close(true);return}if(a==='scan'){closeFinders();return window.TRANSFER_SCAN_DRAWER?.show(b)}if(a==='draft-clear'){E.pending=blankPending();window.render();$('#mx-transfer-search')?.focus();return}if(a==='replace'||a==='replace-color'||a==='replace-fit')return beginReplace(b.dataset.key,a==='replace-fit'?'fit':'color');if(a==='replace-apply')return applyReplace();if(a==='replace-cancel')return cancelReplace();});
document.addEventListener('keydown',e=>{if(!active()||e.isComposing)return;if(e.target.classList?.contains('mx-spec-picker')&&['Enter',' ','ArrowDown'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();openSpecMenu(e.target);sharedSpecMenu.element.querySelector('[aria-selected="true"]')?.focus();return}if(e.key==='Escape'&&sharedSpecMenu.anchor){e.preventDefault();e.stopImmediatePropagation();return closeSpecMenu(true)}if(e.key==='Escape'&&E.pending.replace&&!document.querySelector('dialog[open],.arco-modal')){e.preventDefault();e.stopImmediatePropagation();return cancelReplace()}if(e.target.id==='mx-transfer-color'&&e.target.tagName==='SELECT'&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();e.target.selectedIndex=Math.max(0,Math.min(e.target.options.length-1,e.target.selectedIndex+(e.key==='ArrowDown'?1:-1)));return}if(e.target.id==='mx-transfer-search'&&e.key==='Enter'&&scanFromSearch(e.target.value)){e.preventDefault();e.stopImmediatePropagation();finder.close();replacementFinder.close();return}if(e.target.id==='mx-transfer-color'&&e.target.tagName==='SELECT'&&e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();if(e.target.value)selectColor(e.target.value);return}if(e.target.id==='mx-transfer-fit'&&e.target.tagName==='SELECT'&&e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();selectFit(e.target.value);return}if(e.target.dataset.mxDraftQty&&['Enter','Tab'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const fields=[...document.querySelectorAll('.mx-draft-row [data-mx-draft-qty]')],next=fields[fields.indexOf(e.target)+(e.shiftKey?-1:1)];if(Number(e.target.value)>0)return commitDraft(e.target.dataset.mxDraftQty,e.target.value,next?.dataset.mxDraftQty||'');(next||$('#mx-transfer-search'))?.focus();next?.select();return}if((e.target.dataset.tQty||e.key==='Tab'&&e.target.dataset.mx==='history-qty')&&['Enter','Tab'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const xs=[...document.querySelectorAll('[data-t-qty]:not([readonly]),[data-mx=history-qty][data-mx-cell-mode=doc]')],next=xs[xs.indexOf(e.target)+(e.shiftKey?-1:1)];(next||$('#mx-transfer-search'))?.focus();next?.select?.()}},true);
function printDocument(doc){return window.TRANSFER_PRINT_TEMPLATE.render(doc,{unsaved:!doc.saved||!!U.dirty?.()})}
function printPreview(){finder.close();return window.TRANSFER_PRINT_TEMPLATE.preview(T.doc,{unsaved:!T.doc?.saved||!!U.dirty?.()})}
function warehouse(id){return D.warehouses.find(w=>w.id===id)?.name||'未选择'}
function report(){
 const data=[['奈爵服饰 调拨单',T.doc.id,T.doc.date,T.doc.status],['调出仓',T.doc.fromName||warehouse(T.doc.from),'调入仓',T.doc.toName||warehouse(T.doc.to)]];
 for(const g of transferSections(rows())){
  data.push([g.name],['货号','颜色','商品名称',...g.sizes.map(s=>s.name),'版型','小计']);
  for(const r of g.rows){
   const p=r.product,values=g.sizes.map(z=>H.matches(p,z).reduce((n,x)=>n+Number(T.doc.q[p.id+'|'+r.c+'|'+x.i]||0),0));
   if(!values.some(x=>x>0))continue;
   data.push([p.displayId||p.id,p.colors[r.c],p.name,...values,C.fit(p.fitId)?.name||p.fit||'未设置版型',values.reduce((n,x)=>n+x,0)]);
  }
 }
 return data;
}
